#!/usr/bin/env bash
# M5: two call values per method, no option. The services corpus case
# generated by this branch's CLI under codec=json, and again with each
# method's proto-wired call added beside its JSON one (spike/m5/two-calls.py);
# the floor program (spike/floor/Main.elm, JSON over Connect) built against
# each, three cold builds, and its sizes.
#   spike/m5.sh WORK CLI_BASE
set -euo pipefail
work="$1"; cli="$2"
here="$(cd "$(dirname "$0")/.." && pwd)"
in="$here/conformance/cases/services/input"
for v in one two; do
  d="$work/$v"; rm -rf "$d"; mkdir -p "$d/app/src"
  "$cli" gen -I "$in" notes.proto --codec json --out "$d/generated" > /dev/null
  if [ $v = two ]; then
    "$cli" gen -I "$in" notes.proto --codec proto --out "$work/proto" > /dev/null
    s=Notes/V1/NotesService.elm
    python3 "$here/spike/m5/two-calls.py" "$d/generated/$s" "$work/proto/$s" "$d/generated/$s.new"
    mv "$d/generated/$s.new" "$d/generated/$s"
    (cd "$here" && mise exec -- elm-format --yes "$d/generated/$s" > /dev/null)
  fi
  printf 'm5 %s service_module_bytes=%s lines=%s\n' $v "$(wc -c < "$d/generated/Notes/V1/NotesService.elm" | tr -d ' ')" "$(wc -l < "$d/generated/Notes/V1/NotesService.elm" | tr -d ' ')"
  cp "$here/spike/floor/Main.elm" "$d/app/src/"
  python3 - "$d/app/elm.json" "$here/src" <<'PY'
import json, sys
json.dump({'type': 'application', 'source-directories': ['src', '../generated', sys.argv[2]], 'elm-version': '0.19.2',
           'dependencies': {'direct': {'elm/bytes': '1.0.8', 'elm/core': '1.0.5', 'elm/http': '2.0.0', 'elm/json': '1.1.4', 'elm/time': '1.0.0'},
                            'indirect': {'elm/file': '1.0.5'}},
           'test-dependencies': {'direct': {}, 'indirect': {}}}, open(sys.argv[1], 'w'), indent=4)
PY
  for r in 1 2 3; do "$here/spike/make.sh" "$d" "m5 $v run$r"; done
  "$here/spike/size.sh" "$d/app/main.js" "m5 $v"
done
